package com.example.blades360;
import java.util.*;
import java.util.regex.*;

/** Conservative label detection: never infer a language from words inside a show name. */
final class IptvLabels {
 static final Map<String,String> LABELS=new LinkedHashMap<>();
 static final Map<String,String> ALIASES=new HashMap<>();
 static final Pattern PREFIX=Pattern.compile("^(?:[\\[({|*#]+\\s*)?([A-Z]{2,3})(?=\\s|[\\]})|:_-])(?:[\\]})|:_-]+|\\s+[|:_-])");
 static {String[] entries={"EN:English:ENG,ENGLISH","US:United States:USA,UNITED STATES","UK:United Kingdom:GB,GBR,UNITED KINGDOM","CA:Canada:CAN,CANADA","AU:Australia:AUS,AUSTRALIA","FR:French / France:FRA,FRE,FRENCH,FRANCE","ES:Spanish / Spain:ESP,SPA,SPANISH,SPAIN","DE:German / Germany:DEU,GER,GERMAN,GERMANY","IT:Italian / Italy:ITA,ITALIAN,ITALY","PT:Portuguese / Portugal:POR,PORTUGUESE,PORTUGAL","BR:Brazil:BRA,BRAZIL","AR:Arabic:ARA,ARABIC","TR:Turkish / Turkey:TUR,TURKISH,TURKEY","NL:Dutch / Netherlands:NLD,DUT,DUTCH,NETHERLANDS","PL:Polish / Poland:POL,POLISH,POLAND","RO:Romanian / Romania:RON,RUM,ROMANIAN,ROMANIA","RU:Russian / Russia:RUS,RUSSIAN,RUSSIA","UA:Ukrainian / Ukraine:UKR,UKRAINIAN,UKRAINE","GR:Greek / Greece:EL,ELL,GRE,GREEK,GREECE","SE:Swedish / Sweden:SV,SWE,SWEDISH,SWEDEN","NO:Norwegian / Norway:NOR,NORWEGIAN,NORWAY","DK:Danish / Denmark:DA,DAN,DANISH,DENMARK","FI:Finnish / Finland:FIN,FINNISH,FINLAND","IN:India:IND,INDIA","HI:Hindi:HIN,HINDI","TA:Tamil:TAM,TAMIL","TE:Telugu:TEL,TELUGU","PA:Punjabi:PAN,PUNJABI","UR:Urdu:URD,URDU","PK:Pakistan:PAK,PAKISTAN","BD:Bangladesh:BGD,BANGLADESH","BN:Bengali:BEN,BENGALI","CN:Chinese / China:ZH,ZHO,CHI,CHINESE,CHINA","JP:Japanese / Japan:JA,JPN,JAPANESE,JAPAN","KR:Korean / Korea:KO,KOR,KOREAN,KOREA","TH:Thai / Thailand:THA,THAI,THAILAND","VN:Vietnamese / Vietnam:VI,VIE,VIETNAMESE,VIETNAM","PH:Philippines / Filipino:FIL,PHILIPPINES,FILIPINO","ID:Indonesian / Indonesia:INDONESIAN,INDONESIA","MY:Malay / Malaysia:MS,MSA,MALAY,MALAYSIA","IL:Hebrew / Israel:HE,HEB,HEBREW,ISRAEL","IR:Persian / Iran:FA,FAS,PER,PERSIAN,IRAN","CZ:Czech / Czechia:CS,CES,CZE,CZECH,CZECHIA","SK:Slovak / Slovakia:SLK,SLO,SLOVAK,SLOVAKIA","HU:Hungarian / Hungary:HUN,HUNGARIAN,HUNGARY","BG:Bulgarian / Bulgaria:BUL,BULGARIAN,BULGARIA","RS:Serbian / Serbia:SR,SRP,SERBIAN,SERBIA","HR:Croatian / Croatia:HRV,CROATIAN,CROATIA","AL:Albanian / Albania:SQ,SQI,ALB,ALBANIAN,ALBANIA","BA:Bosnian / Bosnia:BS,BOS,BOSNIAN,BOSNIA","MX:Mexico:MEX,MEXICO","LAT:Latin America:LATINO,LATIN,LATAM","AF:Africa:AFRICA","ZA:South Africa:ZAF,SOUTH AFRICA","IE:Ireland:IRL,IRELAND","NZ:New Zealand:NZL,NEW ZEALAND"};for(String entry:entries){String[] parts=entry.split(":");LABELS.put(parts[0],parts[1]);ALIASES.put(parts[0],parts[0]);for(String alias:parts[2].split(","))ALIASES.put(alias,parts[0]);}LABELS.put("OTHER","Unlabelled / other");}
 static {for(String code:Locale.getISOCountries()){Locale country=new Locale("",code);String name=country.getDisplayCountry(Locale.ENGLISH);if(!LABELS.containsKey(code))LABELS.put(code,name);ALIASES.putIfAbsent(code,code);ALIASES.putIfAbsent(name.toUpperCase(Locale.ROOT),code);try{ALIASES.putIfAbsent(country.getISO3Country(),code);}catch(Exception ignored){}}LABELS.put("AR","Arabic / Argentina");}
 static String normalize(String s){return s==null?"":s.trim().toUpperCase(Locale.ROOT);}
 static void metadata(Set<String> out,String s){for(String token:normalize(s).split("[,;/|]")){String code=ALIASES.get(token.trim());if(code!=null)out.add(code);}}
 static void prefix(Set<String> out,String s){String value=normalize(s);String exact=ALIASES.get(value);if(exact!=null){out.add(exact);return;}Matcher m=PREFIX.matcher(value);if(m.find()){String code=ALIASES.get(m.group(1));if(code!=null)out.add(code);}}
 static Set<String> tags(IptvData.Channel c){Set<String> tags=new LinkedHashSet<>();metadata(tags,c.language);metadata(tags,c.country);prefix(tags,c.group);prefix(tags,c.name);if(tags.isEmpty())tags.add("OTHER");return tags;}
 static String label(String code){return code.equals("OTHER")?LABELS.get(code):code+" · "+LABELS.getOrDefault(code,code);}
}
